use super::*;

unit_enum!(world_protocol::failure::FailureStage, FailureStage; Decode, Admission, Read, Parse, Generate, Resolve, Validate, Compile, Prepare, Execute, Verify, Commit, Activate, Migrate, Drain, Stop, Recover, Disclose);
unit_enum!(world_protocol::failure::InputLimit, InputLimit; Bytes, Depth, Items, StringLength);
variant!(world_protocol::failure::InputFailure, InputFailure; units []; tuples []; records [MissingField { field } => InputFailureMissingField, InvalidValue { field } => InputFailureInvalidValue, InvalidUnit { field } => InputFailureInvalidUnit, LimitExceeded { limit, maximum } => InputFailureLimitExceeded, SchemaMismatch { contract_id, expected } => InputFailureSchemaMismatch, UnresolvedReference { resource } => InputFailureUnresolvedReference, UnknownField { field } => InputFailureUnknownField]);
variant!(world_protocol::failure::Recovery, Recovery; units [None, Refresh, ManualReview]; tuples []; records [CorrectInput { fields } => RecoveryCorrectInput, Rebase { current_revision } => RecoveryRebase, SupplyDependency { contract_id } => RecoverySupplyDependency, RestoreCredential { source_id } => RecoveryRestoreCredential, RetryRead { after } => RecoveryRetryRead, ResumeOperation { operation_id, after } => RecoveryResumeOperation, ReadCommit { commit_id } => RecoveryReadCommit, ReadTransfer { transfer_id } => RecoveryReadTransfer, InspectEffect { operation_id, step_id } => RecoveryInspectEffect, RequestEvidence { evidence } => RecoveryRequestEvidence]);
record!(world_protocol::failure::Failure<world_protocol::actions::ActionFailure>, FailureActionFailure; code, stage, message, diagnostic_id, operation_id, run_id, step_id, details, recovery);
record!(world_protocol::failure::Failure<world_protocol::process::HostFailure>, FailureHostFailure; code, stage, message, diagnostic_id, operation_id, run_id, step_id, details, recovery);
